import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.find.js";
import "core-js/modules/es.iterator.for-each.js";
import "core-js/modules/es.iterator.map.js";
/* eslint-disable */
import { add_remove_member_cabinet } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";
export default {
  props: {
    addMemberDialog: Boolean,
    rowInfo: Object
  },
  mixins: [get_all_org_users],
  data() {
    return {
      loading: false,
      saveLoading: false,
      tableLoading: false,
      selectedUser: null,
      search: "",
      currentMembers: [],
      availableUsers: [],
      memberHeaders: [{
        title: "Name",
        value: "full_user_name",
        sortable: false
      }, {
        title: "Email",
        value: "user_email_id",
        sortable: false
      }, {
        title: "Actions",
        value: "actions",
        sortable: false
      }]
    };
  },
  watch: {
    addMemberDialog: {
      async handler() {
        if (this.addMemberDialog == true) {
          await this.initialize_data();
        }
      },
      immediate: true
    }
  },
  methods: {
    async initialize_data() {
      this.tableLoading = true;
      await this.get_all_org_users();
      this.load_current_members();
      this.load_available_users();
      this.tableLoading = false;
    },
    load_current_members() {
      this.currentMembers = [];
      if (this.rowInfo.folder_visibility) {
        if (this.rowInfo.folder_visibility.visible_type === "ALL_MEMBERS") {
          // For ALL_MEMBERS, show all active users
          this.orgUsers.forEach(user => {
            if (user.user_status === "ACTIVE") {
              this.currentMembers.push({
                user_id: [user.user_id],
                full_user_name: user.full_user_name,
                user_email_id: user.user_email_id
              });
            }
          });
        } else if (this.rowInfo.folder_visibility.visible_type === "RESTRICTED_MEMBERS") {
          // For RESTRICTED_MEMBERS, show only the visible members
          this.rowInfo.folder_visibility.visible_members.forEach(memberId => {
            const user = this.orgUsers.find(u => u.user_id === memberId);
            if (user) {
              this.currentMembers.push({
                user_id: user.user_id,
                full_user_name: user.full_user_name,
                user_email_id: user.user_email_id
              });
            }
          });
        }
      }
    },
    load_available_users() {
      this.availableUsers = [];
      const currentMemberIds = this.currentMembers.map(m => m.user_id);
      this.orgUsers.forEach(user => {
        if (user.user_status === "ACTIVE" && !currentMemberIds.includes(user.user_id)) {
          this.availableUsers.push({
            user_id: user.user_id,
            full_user_name: user.full_user_name,
            user_email_id: user.user_email_id
          });
        }
      });
    },
    async add_member() {
      if (!this.selectedUser) return;
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(add_remove_member_cabinet, {
          input: {
            folder_id: this.rowInfo.folder_id,
            user_id: this.selectedUser,
            action_type: "ADD"
          }
        }));
        var response = JSON.parse(result.data.add_remove_member_cabinet);
        this.loading = false;
        if (response.Status === "SUCCESS") {
          this.$emit("successMsg", "Member added successfully!");
          this.close_dialog();
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    },
    async remove_member(item) {
      // Don't allow removing the owner
      try {
        const result = await API.graphql(graphqlOperation(add_remove_member_cabinet, {
          input: {
            folder_id: this.rowInfo.folder_id,
            user_id: item.user_id,
            action_type: "REMOVE"
          }
        }));
        var response = JSON.parse(result.data.add_remove_member_cabinet);
        if (response.Status === "SUCCESS") {
          this.$emit("successMsg", "Member removed successfully!");
          this.close_dialog();
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.$emit("errorMsg", error.errors[0].message);
      }
    },
    close_dialog() {
      this.selectedUser = null;
      this.currentMembers = [];
      this.availableUsers = [];
      this.search = "";
      this.$emit("clicked", 0);
    }
  }
};
